CREATE TABLE IF NOT EXISTS unit_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, transaction_ref VARCHAR(100) UNIQUE NOT NULL, user_id INTEGER NOT NULL, type VARCHAR(50) NOT NULL, units INTEGER NOT NULL, amount_usd DECIMAL(10,2) NOT NULL, booking_id INTEGER, description TEXT, command_code VARCHAR(100) DEFAULT NULL, status VARCHAR(50) DEFAULT 'completed', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
